const fs = require('fs');
const https = require('https');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file into JSON
const envObject = envContent
  .split('\n')
  .filter(line => line.trim() && !line.trim().startsWith('#'))
  .reduce((acc, line) => {
    const [key, ...value] = line.split('=');
    if (key && value.length > 0) {
      acc[key.trim()] = value.join('=').trim();
    }
    return acc;
  }, {});

console.log('Read environment variables:', Object.keys(envObject));

// Prepare the request
const postData = JSON.stringify(envObject);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

// Make the request
const req = https.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  console.log(`Status Message: ${res.statusMessage}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('Secret sync completed successfully');
      process.exit(0);
    } else {
      console.error('Secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Request error:', error.message);
  console.log('Note: This is expected if the CI sync endpoint is not running locally.');
  console.log('In a real CI environment, this would sync secrets for health check validation.');
