const express = require('express');
const { Client } = require('pg');
const app = express();

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

// Database client setup
const dbClient = new Client({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false,
  connectionTimeoutMillis: 5000, // 5 second timeout for health checks
});

let dbConnected = false;

// Try to connect to database on startup
async function initializeDatabase() {
  try {
    await dbClient.connect();
    dbConnected = true;
    console.log('Database connected successfully');
  } catch (error) {
    console.error('Failed to connect to database:', error.message);
    dbConnected = false;
  }
}

// Initialize database connection
initializeDatabase();

// Health check endpoint for k8s readiness probe
app.get('/healthz', async (req, res) => {
  if (!dbConnected) {
    // Try to reconnect if not connected
    try {
      await dbClient.connect();
      dbConnected = true;
    } catch (error) {
      return res.status(503).json({ 
        db: 'unhealthy',
        error: error.message,
        timestamp: new Date().toISOString()
      });
    }
  }

  try {
    // Simple query to verify database connectivity
    const result = await dbClient.query('SELECT 1 as healthy');
    if (result.rows[0].healthy === 1) {
      return res.status(200).json({ db: 'ok' });
    } else {
      throw new Error('Unexpected query result');
    }
  } catch (error) {
    dbConnected = false;
    return res.status(503).json({ 
      db: 'unhealthy',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

