  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('SIGTERM signal received: closing HTTP server and database connection');
  try {
    await dbClient.end();
  } catch (error) {
    console.error('Error closing database connection:', error);
  }
  process.exit(0);
});

