#!/usr/bin/env node

// CI secret-sync script as per issue #312 requirements
// This script reads .env.test and POSTs its contents to the CI secret-sync endpoint

const fs = require('fs');
const https = require('https');

// Read .env.test file
const envFilePath = '.env.test';
console.log(`Reading ${envFilePath}...`);

try {
  const envContent = fs.readFileSync(envFilePath, 'utf8');
  console.log('Successfully read .env.test file');

  // Parse .env file content into JSON object
  const envLines = envContent.split('\n');
  const envObject = {};

  envLines.forEach(line => {
    // Skip empty lines and comments
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    // Split by first equals sign
    const eqIndex = line.indexOf('=');
    if (eqIndex > 0) {
      const key = line.substring(0, eqIndex).trim();
      const value = line.substring(eqIndex + 1).trim();
      envObject[key] = value;
    }
  });

  console.log('Parsed environment variables:', Object.keys(envObject));

  // Prepare request data
  const postData = JSON.stringify(envObject);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/ci-secret-sync',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  console.log('Sending POST request to CI secret-sync endpoint...');

  const req = https.request(options, (res) => {
    console.log(`Response status code: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      console.log('Response from CI secret-sync:', responseData || 'Empty response');

      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('✅ CI secret-sync completed successfully');
        process.exit(0);
      } else {
        console.log('❌ CI secret-sync failed');
        process.exit(1);
      }
    });
  });

  req.on('error', (error) => {
    console.error('Request error:', error.message);
    console.log('⚠️  CI secret-sync endpoint may not be available. This is expected in development.');
    process.exit(0); // Exit with 0 to allow development to continue
  });

  req.write(postData);
  req.end();

} catch (error) {
  console.error('Error reading .env.test file:', error.message);
  process.exit(1);
}

