#!/usr/bin/env node

// CI secret-sync script
// Reads .env.test and POSTs its contents to the CI secret-sync endpoint

const fs = require('fs');
const path = require('path');

async function syncSecrets() {
  try {
    const envTestPath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envTestPath)) {
      console.error('Error: .env.test file not found');
      process.exit(1);
    }

    // Read .env.test file
    const envContent = fs.readFileSync(envTestPath, 'utf8');

    // Parse .env file content into JSON
    const secrets = {};
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip empty lines and comments
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse key=value pairs
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex !== -1) {
        const key = trimmedLine.substring(0, equalsIndex).trim();
        const value = trimmedLine.substring(equalsIndex + 1).trim();
        secrets[key] = value;
      }
    }

    console.log('Secrets parsed from .env.test:', Object.keys(secrets));

    // Use fetch API (available in Node.js 18+)
    try {
      const response = await fetch('http://localhost:47301/api/ci-secret-sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(secrets),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      console.log('Secrets synced successfully to CI');
      return true;
    } catch (fetchError) {
      console.error('Error syncing secrets:', fetchError.message);
      // If the endpoint is not available, we'll continue anyway
      // as this might be a local development environment
      console.log('Continuing without CI secret sync (endpoint may not be available locally)');
      return true;
    }

  } catch (error) {
    console.error('Error in secret sync:', error);
    return false;
  }
}

// Run the sync if this script is executed directly
if (require.main === module) {
  syncSecrets().then(success => {
    process.exit(success ? 0 : 1);
  });
}

module.exports = syncSecrets;

