    const req = http.request(options, (res) => {
      console.log(`Status Code: ${res.statusCode}`);

      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        console.log('Response:', data);
        server.close();
        process.exit(res.statusCode === 200 ? 0 : 1);
      });
    });

    req.on('error', (error) => {
      console.error('Error testing healthz endpoint:', error);
      server.close();
      process.exit(1);
    });

    req.end();
  }, 1000);
});

// Handle shutdown
process.on('SIGINT', () => {
  server.close();
