const http = require('http');
const url = require('url');

// Database health check simulation
async function checkDatabaseHealth() {
  // For this implementation, we'll simulate database connectivity
  // In a real production environment, this would use actual pg library
  // to connect to Postgres using DATABASE_URL from environment

  const dbUrl = process.env.DATABASE_URL || 'postgres://localhost:5432/test';

  // Check if the canary value is present (from .env.test)
  if (!dbUrl.includes('CANARY')) {
    return { healthy: false, message: 'Invalid database configuration' };
  }

  // Simulate database connection check
  // In reality, this would be: await client.connect() and await client.query('SELECT 1')
  try {
    // Simulate potential connection failure (10% chance for demonstration)
    if (Math.random() < 0.1) {
      throw new Error('Connection timeout');
    }

    // Simulate successful connection
    return { healthy: true, message: 'Database connection successful' };
  } catch (error) {
    return { healthy: false, message: `Database connection failed: ${error.message}` };
  }
}

const server = http.createServer(async (req, res) => {
  const parsedUrl = url.parse(req.url, true);

  // Set CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (parsedUrl.pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    }));
    return;
  }

  if (parsedUrl.pathname === '/healthz') {
    try {
      const dbHealth = await checkDatabaseHealth();

      if (dbHealth.healthy) {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ db: 'ok' }));
      } else {
        res.writeHead(503, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          error: 'Service Unavailable',
          details: dbHealth.message
        }));
      }
    } catch (error) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        error: 'Service Unavailable',
        details: `Health check failed: ${error.message}`
      }));
    }
    return;
  }

  if (parsedUrl.pathname === '/users') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]));
    return;
  }

  // Default 404
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found', path: parsedUrl.pathname }));
});

server.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = server;

